if ($request_method === 'POST') {
    $action = trim((string) (filter_input(INPUT_POST, 'action', FILTER_UNSAFE_RAW) ?? ''));
    $schedule_id = filter_input(
        INPUT_POST,
        'schedule_id',
        FILTER_VALIDATE_INT,
        [
            'options' => [
                'min_range' => 1,
            ],
        ]
    );

    try {
        switch ($action) {
            case 'approve_schedule':
