/* =========================================================
   Bootstrap-like flash alerts
   Scope: GLPI messages after redirect / alerts
   ========================================================= */

.vs-flash {
    --vs-alert-color: #052c65;
    --vs-alert-bg: #cfe2ff;
    --vs-alert-border: #9ec5fe;
    --vs-alert-icon-bg: rgba(255, 255, 255, 0.56);

    position: relative;
    width: 100%;
    min-height: 52px;
    gap: 12px;
    margin: 0 0 16px !important;
    padding: 14px 48px 14px 16px !important;
    border: 1px solid var(--vs-alert-border) !important;
    border-radius: 6px !important;
    background: var(--vs-alert-bg) !important;
    color: var(--vs-alert-color) !important;
    box-shadow: none !important;
}

.vs-flash,
.vs-flash * {
    color: var(--vs-alert-color) !important;
    font-weight: 500;
}

.vs-flash__icon {
    width: 22px;
    height: 22px;
    display: inline-flex;
    flex: 0 0 22px;
    align-items: center;
    justify-content: center;
    margin-top: 1px;
    border-radius: 999px;
    background: var(--vs-alert-icon-bg);
    font-size: 14px;
    font-weight: 800;
    line-height: 1;
}

.vs-flash__icon::before {
    content: "i";
}

.vs-flash__icon[data-vs-flash-icon="success"]::before,
.vs-flash__icon[data-vs-flash-icon="check"]::before {
    content: "\2713";
}

.vs-flash__icon[data-vs-flash-icon="warning"]::before,
.vs-flash__icon[data-vs-flash-icon="danger"]::before {
    content: "!";
}

.vs-flash__body {
    flex: 1 1 auto;
    min-width: 0;
}

.vs-flash__body [data-vs-flash-kind] {
    display: block;
}

.vs-flash__dismiss {
    position: absolute;
    top: 10px;
    right: 12px;
    width: 28px;
    height: 28px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--vs-alert-color) !important;
    font-size: 24px;
    font-weight: 300;
    line-height: 1;
    opacity: 0.65;
    cursor: pointer;
}

.vs-flash__dismiss:hover,
.vs-flash__dismiss:focus {
    background: rgba(0, 0, 0, 0.06);
    opacity: 1;
}

.vs-flash .ui-pnotify-title,
.vs-flash .ui-pnotify-sticker,
.vs-flash .ui-pnotify-closer,
.vs-flash .ui-pnotify-icon {
    display: none !important;
}

.vs-flash--success {
    --vs-alert-color: #0a3622;
    --vs-alert-bg: #d1e7dd;
    --vs-alert-border: #a3cfbb;
}

.vs-flash--error {
    --vs-alert-color: #58151c;
    --vs-alert-bg: #f8d7da;
    --vs-alert-border: #f1aeb5;
}

.vs-flash--warning {
    --vs-alert-color: #664d03;
    --vs-alert-bg: #fff3cd;
    --vs-alert-border: #ffda6a;
}

.vs-flash--info {
    --vs-alert-color: #055160;
    --vs-alert-bg: #cff4fc;
    --vs-alert-border: #9eeaf9;
}

.vs-dark .vs-flash--success {
    --vs-alert-color: #d1e7dd;
    --vs-alert-bg: rgba(25, 135, 84, 0.22);
    --vs-alert-border: rgba(163, 207, 187, 0.42);
}

.vs-dark .vs-flash--error {
    --vs-alert-color: #f8d7da;
    --vs-alert-bg: rgba(220, 53, 69, 0.22);
    --vs-alert-border: rgba(241, 174, 181, 0.42);
}

.vs-dark .vs-flash--warning {
    --vs-alert-color: #fff3cd;
    --vs-alert-bg: rgba(255, 193, 7, 0.20);
    --vs-alert-border: rgba(255, 218, 106, 0.42);
}

.vs-dark .vs-flash--info {
    --vs-alert-color: #cff4fc;
    --vs-alert-bg: rgba(13, 202, 240, 0.18);
    --vs-alert-border: rgba(158, 234, 249, 0.42);
}

