/* =========================================================
   Design-system style flash alerts
   Scope: GLPI messages after redirect / alerts
   ========================================================= */

.vs-flash {
    --vs-alert-color: #075985;
    --vs-alert-muted: #0369a1;
    --vs-alert-bg: #f0f9ff;
    --vs-alert-border: #bae6fd;
    --vs-alert-icon-bg: #e0f2fe;

    position: relative;
    width: 100%;
    margin: 0 0 16px !important;
    padding: 16px 48px 16px 18px !important;
    border: 1px solid var(--vs-alert-border) !important;
    border-radius: 8px !important;
    background: var(--vs-alert-bg) !important;
    color: var(--vs-alert-color) !important;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04) !important;
}

.vs-flash > :not(.vs-flash__body):not(.vs-flash__dismiss) {
    display: none !important;
}

.vs-flash,
.vs-flash * {
    color: inherit !important;
}

.vs-flash__body {
    min-width: 0;
}

.vs-flash__title {
    display: flex;
    align-items: center;
    gap: 8px;
    color: var(--vs-alert-color) !important;
    font-size: 15px;
    font-weight: 650;
    line-height: 1.25;
}

.vs-flash__icon {
    width: 22px;
    height: 22px;
    display: inline-flex;
    flex: 0 0 22px;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: var(--vs-alert-icon-bg);
    color: var(--vs-alert-color) !important;
    font-size: 14px;
    font-weight: 800;
    line-height: 1;
}

.vs-flash__icon::before {
    content: "i";
}

.vs-flash__icon[data-vs-flash-icon="success"]::before,
.vs-flash__icon[data-vs-flash-icon="check"]::before {
    content: "\2713";
}

.vs-flash__icon[data-vs-flash-icon="warning"]::before,
.vs-flash__icon[data-vs-flash-icon="danger"]::before {
    content: "!";
}

.vs-flash__message {
    margin-top: 8px;
    padding-left: 30px;
    color: var(--vs-alert-muted) !important;
    font-size: 14px;
    font-weight: 450;
    line-height: 1.45;
}

.vs-flash__message [data-vs-flash-kind] {
    display: block;
}

.vs-flash__dismiss {
    position: absolute;
    top: 10px;
    right: 12px;
    width: 28px;
    height: 28px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: var(--vs-alert-color) !important;
    font-size: 22px;
    font-weight: 300;
    line-height: 1;
    opacity: 0.58;
    cursor: pointer;
}

.vs-flash__dismiss:hover,
.vs-flash__dismiss:focus {
    background: rgba(120, 53, 15, 0.08);
    opacity: 1;
}

.vs-flash .btn-close,
.vs-flash .close,
.vs-flash [data-bs-dismiss="alert"],
.vs-flash .ui-pnotify-title,
.vs-flash .ui-pnotify-sticker,
.vs-flash .ui-pnotify-closer,
.vs-flash .ui-pnotify-icon {
    display: none !important;
}

.vs-flash--success {
    --vs-alert-color: #166534;
    --vs-alert-muted: #15803d;
    --vs-alert-bg: #f0fdf4;
    --vs-alert-border: #bbf7d0;
    --vs-alert-icon-bg: #dcfce7;
}

.vs-flash--error {
    --vs-alert-color: #991b1b;
    --vs-alert-muted: #b91c1c;
    --vs-alert-bg: #fef2f2;
    --vs-alert-border: #fecaca;
    --vs-alert-icon-bg: #fee2e2;
}

.vs-flash--warning {
    --vs-alert-color: #78350f;
    --vs-alert-muted: #854d0e;
    --vs-alert-bg: #fffbeb;
    --vs-alert-border: #fcd34d;
    --vs-alert-icon-bg: #fef3c7;
}

.vs-flash--info {
    --vs-alert-color: #075985;
    --vs-alert-muted: #0369a1;
    --vs-alert-bg: #f0f9ff;
    --vs-alert-border: #bae6fd;
    --vs-alert-icon-bg: #e0f2fe;
}

.vs-dark .vs-flash--success {
    --vs-alert-color: #bbf7d0;
    --vs-alert-muted: #86efac;
    --vs-alert-bg: rgba(22, 101, 52, 0.18);
    --vs-alert-border: rgba(187, 247, 208, 0.30);
    --vs-alert-icon-bg: rgba(22, 101, 52, 0.32);
}

.vs-dark .vs-flash--error {
    --vs-alert-color: #fecaca;
    --vs-alert-muted: #fca5a5;
    --vs-alert-bg: rgba(153, 27, 27, 0.18);
    --vs-alert-border: rgba(254, 202, 202, 0.30);
    --vs-alert-icon-bg: rgba(153, 27, 27, 0.32);
}

.vs-dark .vs-flash--warning {
    --vs-alert-color: #fde68a;
    --vs-alert-muted: #fcd34d;
    --vs-alert-bg: rgba(120, 53, 15, 0.20);
    --vs-alert-border: rgba(252, 211, 77, 0.34);
    --vs-alert-icon-bg: rgba(120, 53, 15, 0.36);
}

.vs-dark .vs-flash--info {
    --vs-alert-color: #bae6fd;
    --vs-alert-muted: #7dd3fc;
    --vs-alert-bg: rgba(7, 89, 133, 0.18);
    --vs-alert-border: rgba(186, 230, 253, 0.30);
    --vs-alert-icon-bg: rgba(7, 89, 133, 0.32);
}

