function vs_vehicle_render_escape(?string $value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

function vs_vehicle_render_cnh_icon(string $category): string
{
    $icons = [
        'A' => 'ti ti-motorbike',
        'B' => 'ti ti-car',
        'D' => 'ti ti-truck',
    ];

    return $icons[$category] ?? 'ti ti-license';
}

