                    </div>

                    <div class="vs-vehicle-field">
                        <div class="vs-vehicle-label">Ano <span class="red">*</span></div>
                        <?= Html::input('year', [
                            'value'       => (int) ($vehicle->fields['year'] ?? (int) date('Y')),
                            'type'        => 'number',
                            'min'         => PluginVehicleschedulerVehicle::MIN_YEAR,
