                                    >
                                    <span class="vs-vehicle-cnh-option__icon">
                                        <i class="<?= vs_vehicle_render_escape(vs_vehicle_render_cnh_icon($category)) ?>"></i>
                                    </span>
                                    <span class="vs-vehicle-cnh-option__meta">
