 *
 * @param string $name Driver full name.
 *
 * @return string
 */
function vs_driver_list_initials(string $name): string
{
    $name = trim($name);

    if ($name === '') {
        return 'M';
    }

    $parts = preg_split('/\s+/', $name) ?: [];
    $initials = '';

    foreach (array_slice($parts, 0, 2) as $part) {
