<?php
function parse_po(string $file): array {
    $lines = file($file, FILE_IGNORE_NEW_LINES);
    $entries = [];
    $msgid = null;
    $msgstr = null;
    $state = null;
    $obsolete = false;
    $flush = function () use (&$entries, &$msgid, &$msgstr, &$obsolete) {
        if (!$obsolete && $msgid !== null && $msgid !== '' && $msgstr !== null && $msgstr !== '') {
            $entries[$msgid] = $msgstr;
        }
        $msgid = null;
        $msgstr = null;
        $obsolete = false;
    };
    foreach ($lines as $line) {
        if ($line === '') {
            $flush();
            $state = null;
            continue;
        }
        if (str_starts_with($line, '#~')) {
            $obsolete = true;
            continue;
        }
        if (preg_match('/^msgid "(.*)"$/', $line, $m)) {
            if ($msgid !== null) {
                $flush();
            }
            $msgid = stripcslashes($m[1]);
            $msgstr = null;
            $state = 'msgid';
            continue;
        }
        if (preg_match('/^msgstr "(.*)"$/', $line, $m)) {
            $msgstr = stripcslashes($m[1]);
            $state = 'msgstr';
            continue;
        }
        if (preg_match('/^"(.*)"$/', $line, $m)) {
            if ($state === 'msgid' && $msgid !== null) {
                $msgid .= stripcslashes($m[1]);
            } elseif ($state === 'msgstr' && $msgstr !== null) {
                $msgstr .= stripcslashes($m[1]);
            }
        }
    }
    $flush();
    return $entries;
}

foreach (['pt_BR', 'en_GB', 'es_ES', 'fr_FR'] as $locale) {
    $phpFile = __DIR__ . "/locales/{$locale}.php";
    $poEntries = parse_po(__DIR__ . "/locales/{$locale}.po");
    $LANG = [];
    include $phpFile;
    $current = $LANG['plugin_vehiclescheduler'] ?? [];
    $missing = array_diff_key($poEntries, $current);
    if (!$missing) {
        continue;
    }
    ksort($missing, SORT_NATURAL | SORT_FLAG_CASE);
    $block = "\n    // Extracted gettext strings\n";
    foreach ($missing as $key => $value) {
        $block .= '    ' . var_export($key, true) . ' => ' . var_export($value, true) . ",\n";
    }
    $content = file_get_contents($phpFile);
    $content = preg_replace('/\n\];\s*$/', $block . '\n];' . PHP_EOL, $content, 1);
    file_put_contents($phpFile, $content);
}
