<?php
function parse_po(string $file): array {
    $blocks = preg_split('/\n\n/', file_get_contents($file));
    $entries = [];
    foreach ($blocks as $block) {
        if (str_contains($block, '#~') || str_contains($block, 'msgid_plural')) continue;
        if (!preg_match('/^msgid "(.*)"$/m', $block, $m)) continue;
        $id = stripcslashes($m[1]);
        if ($id === '') continue;
        if (!preg_match('/^msgstr "(.*)"$/m', $block, $s)) continue;
        $str = stripcslashes($s[1]);
        if ($str === '') continue;
        $entries[$id] = $str;
    }
    ksort($entries, SORT_NATURAL | SORT_FLAG_CASE);
    return $entries;
}
foreach (['pt_BR', 'en_GB', 'es_ES', 'fr_FR'] as $locale) {
    $entries = parse_po(__DIR__ . "/locales/{$locale}.po");
    $content = "<?php\n\n/**\n * Generated translation map for the vehiclescheduler plugin.\n */\n\n";
    $content .= "\$LANG['plugin_vehiclescheduler'] = [\n";
    foreach ($entries as $key => $value) {
        $content .= '    ' . var_export($key, true) . ' => ' . var_export($value, true) . ",\n";
    }
    $content .= "];\n";
    file_put_contents(__DIR__ . "/locales/{$locale}.php", $content);
}
